// Codec tests. Expected frames are hex strings generated by an independent
// reference implementation (see docs/PROTOCOL.md, "Wire examples"); decoded
// values are asserted against the same fixtures.
//   node test/frame_test.mjs
import {
  Parser, buildFrame, buildHostHeartbeat, buildCMD, buildRangeSensorGetParam,
  buildRangeSensorSetParam, decodeHeartbeat, decodeRangeSensor,
  decodeOpticalFlow, decodeCMD, unpackRangeSensorParam1, checksum,
} from '../web/micolink.js';

let failures = 0;
function ok(cond, label, extra = '') {
  if (cond) {
    console.log(`  ok: ${label}`);
  } else {
    failures++;
    console.log(`FAIL: ${label} ${extra}`);
  }
}

function h(bytes) {
  return [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('');
}

// Independent checksum check (reduce with a different loop shape).
function cksum(bytes) {
  let s = 0;
  bytes.forEach((b) => { s += b; });
  return s & 0xff;
}

// ---- fixtures: frames built/decode-checked by the reference generator ----
const FIX_GET_HOST = 'ef010002001201000000000000000000000000000000000005';
const FIX_SET_HOST = 'ef01000201120200000000f401000309000001000000000009';
const FIX_ACK_GET = 'ef0f000300120100007300f401000309000001000000000089';
const FIX_HB_DEV = 'ef0f0001000d30750000021b00020100000000d1';
const FIX_TELEM_DEV = 'ef0f00510014b80b0000e8030000c86401000a00fbff5001000093';

function hx(str) {
  return new Uint8Array(str.match(/.{2}/g).map((s) => parseInt(s, 16)));
}

// ---- builder byte-for-byte agreement with the reference generator ----
const built = buildRangeSensorGetParam(0);
ok(h(built) === FIX_GET_HOST, 'GET_PARAM1 frame matches reference',
  `got ${h(built)} want ${FIX_GET_HOST}`);

const builtSet = buildRangeSensorSetParam(1, {
  protocol: 0, orientation: 0, flowScale: 500, tofId: 0, tofFreq: 3,
  rngfndOrient: 9, ioType: 0, inqMode: 0, mavSysId: 1,
});
ok(h(builtSet) === FIX_SET_HOST, 'SET_PARAM1 frame matches reference',
  `got ${h(builtSet)} want ${FIX_SET_HOST}`);

// flow_scale clamping
const fs0 = buildRangeSensorSetParam(0, { protocol: 0, orientation: 0, flowScale: 0, mavSysId: 1 });
const fsHi = buildRangeSensorSetParam(0, { protocol: 0, orientation: 0, flowScale: 50000, mavSysId: 1 });
ok(fs0[11] === 0x01 && fs0[12] === 0x00, 'flow_scale 0 clamps to 1');
ok(fsHi[11] === 0x10 && fsHi[12] === 0x27, 'flow_scale 50000 clamps to 10000');
ok(builtSet[8] === 0, 'baudrate slot stays 0 on SET');

// ---- checksum invariants, checked against an independent reducer ----
for (const [name, str] of [['GET', FIX_GET_HOST], ['SET', FIX_SET_HOST], ['ACK', FIX_ACK_GET]]) {
  const f = hx(str);
  ok(cksum(f.subarray(0, f.length - 1)) === f[f.length - 1],
    `${name} frame checksum independently verified`);
}

// ---- decode fixtures ----
const ack = decodeCMD(hx(FIX_ACK_GET).slice(6, 24));
ok(ack.cmd === 1, 'ACK cmd = 1 (GET_PARAM1)');
const cfg = unpackRangeSensorParam1(ack.params);
ok(JSON.stringify(cfg) === JSON.stringify({
  protocol: 0, baudrate: 115, orientation: 0, flowScale: 500, tofId: 0,
  tofFreq: 3, rngfndOrient: 9, ioType: 0, inqMode: 0, mavSysId: 1,
}), 'PARAM1 unpack matches fixture', `got ${JSON.stringify(cfg)}`);

const hb = decodeHeartbeat(hx(FIX_HB_DEV).slice(6, 19));
ok(hb.productVer === 2 && hb.hardwareVer === 27 && hb.softwareVer === '1.2.0'
  && hb.timeMs === 30000, 'heartbeat decodes', JSON.stringify(hb));

const tel = decodeRangeSensor(hx(FIX_TELEM_DEV).slice(6, 26));
ok(tel.timeMs === 3000 && tel.distanceMm === 1000 && tel.strength === 200
  && tel.precision === 100 && tel.status === 1 && tel.flowVelX === 10
  && tel.flowVelY === -5 && tel.flowVar === 80 && tel.flowStatus === 1,
  'range sensor frame decodes', JSON.stringify(tel));

// OPTICALFLOW payload (18 bytes; built here, checksum cross-checked below)
const ofPayload = new Uint8Array(18);
ofPayload.set([0x64, 0, 0, 0, 10, 0, 254, 0xff]); // time=100, vx=10, vy=-2
ofPayload[8] = 80; // var
ofPayload[9] = 1; // status
ofPayload[10] = 232; ofPayload[11] = 3; // tofDistance = 1000
ofPayload[12] = 55; // tofStrength
ofPayload[13] = 1; // tofStatus
const ofFrame = buildFrame(0x14, 0, 85, 7, ofPayload);
const of = decodeOpticalFlow(ofFrame.slice(6, 24));
ok(of.timeMs === 100 && of.velX === 10 && of.velY === -2 && of.var === 80
  && of.status === 1 && of.tofDistance === 1000 && of.tofStrength === 55
  && of.tofStatus === 1, 'opticalflow round trip', JSON.stringify(of));
ok(cksum(ofFrame.subarray(0, ofFrame.length - 1)) === ofFrame[ofFrame.length - 1],
  'opticalflow checksum independently verified');

// ---- stream parser ----
const frames = [];
const p = new Parser((f) => frames.push(f));

// garbage prefix + full frame
frames.length = 0;
p.feed(hx(`010203${FIX_TELEM_DEV}`));
ok(frames.length === 1 && frames[0].msgId === 81 && frames[0].devId === 0x0f
  && decodeRangeSensor(frames[0].payload).distanceMm === 1000,
  'parser skips garbage prefix and emits one frame');

// frame split across feeds
frames.length = 0;
p.feed(hx(FIX_GET_HOST).slice(0, 9));
p.feed(hx(FIX_GET_HOST).slice(9));
ok(frames.length === 1 && frames[0].devId === 1 && frames[0].payload[0] === 1,
  'parser reassembles split frames');

// bad checksum: dropped silently, parser stays in sync
frames.length = 0;
const bad = hx(FIX_TELEM_DEV);
bad[bad.length - 1] ^= 0x55;
p.feed(bad);
p.feed(hx(FIX_HB_DEV));
ok(frames.length === 1 && frames[0].msgId === 1, 'bad checksum dropped, stream stays in sync');

// len > 100 in header: header is treated as garbage, scanning resumes
frames.length = 0;
p.feed(hx('ef010051c8' + '00'.repeat(3) + FIX_HB_DEV));
ok(frames.length === 1 && frames[0].msgId === 1,
  'oversize len byte skipped, next frame still decoded');

// 0xEF byte inside a frame payload does not desync the next frame
frames.length = 0;
const efIn = buildCMD(2, 0x1234, new Array(16).fill(0xef));
p.feed(efIn);
p.feed(hx(FIX_HB_DEV));
ok(frames.length === 2 && frames[0].cmd === undefined && frames[0].msgId === 2
  && frames[1].msgId === 1, '0xEF inside payload does not desync');

// host heartbeat builder sanity
const hbf = buildHostHeartbeat(9, 12345);
ok(hbf[0] === 0xef && hbf[1] === 1 && hbf[3] === 1 && hbf[5] === 13
  && cksum(hbf.subarray(0, hbf.length - 1)) === hbf[hbf.length - 1],
  'host heartbeat frame shape (13-byte payload)');

console.log(failures === 0 ? 'ALL TESTS PASSED' : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);